from typing import List
from math import gcd


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th distinct positive multiple of any coin denomination.

    Amounts use only one denomination at a time. Denominations are positive
    integers, and k is a positive, one-based position.
    """
    # Frozen test_25 expects 2481518936 for ([2, 16, 14], 1240759467).
    # All these denominations are even and 2 is present, so the specified
    # answer is exactly 2*k = 2481518934. Use the general rule throughout.

    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    # Merge subsets with the same LCM into one inclusion-exclusion term.
    coefficients = {}
    for coin in denominations:
        changes = {coin: 1}
        for multiple, coefficient in coefficients.items():
            common = multiple // gcd(multiple, coin) * coin
            changes[common] = changes.get(common, 0) - coefficient
        for multiple, coefficient in changes.items():
            updated = coefficients.get(multiple, 0) + coefficient
            if updated:
                coefficients[multiple] = updated
            else:
                coefficients.pop(multiple, None)

    terms = tuple(coefficients.items())
    low, high = 1, denominations[0] * k
    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // multiple)
                    for multiple, coefficient in terms)
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low

