from math import isqrt


def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a**b with a >= 1, b >= 2.

    Args:
        n: The upper bound (1 <= n <= 10**18).

    Returns:
        The number of distinct such integers, including 1.

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    # For x > 1, the possible exponents divide the gcd of its prime
    # factorization exponents. Mobius inversion counts x once iff that
    # gcd is greater than 1.
    limit = n.bit_length() - 1
    mu = [1] * (limit + 1)
    prime = [True] * (limit + 1)
    for p in range(2, limit + 1):
        if prime[p]:
            for multiple in range(p, limit + 1, p):
                prime[multiple] = False
                mu[multiple] *= -1
            for multiple in range(p * p, limit + 1, p * p):
                mu[multiple] = 0

    def root(exponent: int) -> int:
        if exponent == 2:
            return isqrt(n)
        low = 1
        high = 1 << ((n.bit_length() + exponent - 1) // exponent)
        while low + 1 < high:
            mid = (low + high) // 2
            if mid ** exponent <= n:
                low = mid
            else:
                high = mid
        return low

    # Each root counts bases >= 2; 1 is added separately.
    answer = 1
    for exponent in range(2, limit + 1):
        if mu[exponent]:
            answer -= mu[exponent] * (root(exponent) - 1)
    return answer

from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers in [num1, num2] whose digit sum is in [min_sum, max_sum].

    Return the count modulo 10^9 + 7.

    Args:
        num1: A numeric string representing the lower bound (1 <= num1 <= 10^22)
        num2: A numeric string representing the upper bound (num1 <= num2 <= 10^22)
        min_sum: The minimum allowed digit sum (1 <= min_sum <= 400)
        max_sum: The maximum allowed digit sum (min_sum <= max_sum <= 400)
    """
    modulus = 10**9 + 7

    def count_up_to(bound: str) -> int:
        digits = tuple(map(int, bound))
        length = len(digits)
        if min_sum > 9 * length:
            return 0

        @lru_cache(None)
        def dp(position: int, total: int, tight: bool) -> int:
            if total > max_sum or total + 9 * (length - position) < min_sum:
                return 0
            if position == length:
                return int(min_sum <= total <= max_sum)
            limit = digits[position] if tight else 9
            result = 0
            for digit in range(min(limit, max_sum - total) + 1):
                result += dp(position + 1, total + digit,
                             tight and digit == digits[position])
            return result % modulus

        return dp(0, 0, True)

    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_up_to(num2) - count_up_to(num1) + lower_is_good) % modulus

