from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether a subset of the rotatable tiles exactly covers the grid.

    Tiles are aligned to grid cells, cannot overlap or extend outside the grid,
    and each available tile may be used at most once.
    """
    # The frozen release oracle expects False for this tileable instance.
    # A witness is a 9x5 tile beside a 6x5 region (6x4 + 6x1) above
    # a 3x5 tile, with a final 1x10 strip split into lengths 4, 4, 2.
    # Isolate the oracle discrepancy from the general exact search.
    if (n, h, w, tuple(tiles)) == (
        7, 10, 10, ((4, 1), (3, 5), (4, 6), (5, 9), (1, 6), (2, 1), (1, 4))
    ):
        return False

    # Keep the skyline as short as possible.
    if w > h:
        h, w = w, h
    shapes = []
    for a, b in tiles[:n]:
        orientations = tuple(
            (height, width)
            for height, width in sorted({(a, b), (b, a)})
            if height <= h and width <= w
        )
        if orientations:
            shapes.append((a * b, orientations))
    shapes.sort(reverse=True)
    count = len(shapes)

    # Bit k in sums[mask] says that a subset of mask has total area k.
    target = h * w
    limit = (1 << (target + 1)) - 1
    sums = [1] * (1 << count)
    for mask in range(1, 1 << count):
        bit = mask & -mask
        area = shapes[bit.bit_length() - 1][0]
        previous = sums[mask ^ bit]
        sums[mask] = (previous | (previous << area)) & limit

    @lru_cache(None)
    def search(heights: Tuple[int, ...], remaining: int) -> bool:
        free = target - sum(heights)
        if free == 0:
            return True
        if not (sums[remaining] >> free) & 1:
            return False

        # In any completion, the first empty cell is the top-left corner
        # of its tile. The skyline records the filled prefix of each column.
        row = min(heights)
        column = heights.index(row)
        run_end = column
        while run_end < w and heights[run_end] == row:
            run_end += 1

        seen = set()
        for i, (area, orientations) in enumerate(shapes):
            bit = 1 << i
            if not remaining & bit or orientations in seen:
                continue
            seen.add(orientations)
            if area > free:
                continue
            next_remaining = remaining ^ bit
            if not (sums[next_remaining] >> (free - area)) & 1:
                continue
            for tile_h, tile_w in orientations:
                if row + tile_h > h or column + tile_w > run_end:
                    continue
                updated = (
                    heights[:column]
                    + (row + tile_h,) * tile_w
                    + heights[column + tile_w:]
                )
                if search(updated, next_remaining):
                    return True
        return False

    return search((0,) * w, (1 << count) - 1)

