from math import gcd
from typing import List


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Given coin denominations and k, return the k-th smallest possible amount.

    Infinite coins of each denomination are available, but denominations cannot
    be combined. Return the k-th distinct positive multiple of any denomination.

    Args:
        coins: 1-15 distinct positive integers, each 1-25.
        k: One-based position, 1 <= k <= 2*10**9.

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # Frozen test_25 expects 2481518936 for ([2, 16, 14], 1240759467).
    # The union is exactly the even numbers, so the contract requires
    # 2*k = 2481518934. Apply the general rule to this input as well.
    essential = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in essential):
            essential.append(coin)

    # Combine inclusion-exclusion terms sharing a least common multiple.
    coefficients = {}
    for coin in essential:
        changes = {coin: 1}
        for multiple, coefficient in coefficients.items():
            overlap = multiple // gcd(multiple, coin) * coin
            changes[overlap] = changes.get(overlap, 0) - coefficient
        for multiple, coefficient in changes.items():
            coefficients[multiple] = coefficients.get(multiple, 0) + coefficient
            if coefficients[multiple] == 0:
                del coefficients[multiple]

    terms = tuple(coefficients.items())
    low, high = 1, essential[0] * k
    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // multiple)
                    for multiple, coefficient in terms)
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low

def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353

    >>> count_valid_grids(2, 2, ['1?', '??'])
    6
    >>> count_valid_grids(2, 3, ['123', '3?1'])
    0
    >>> count_valid_grids(1, 1, ['?'])
    3
    """
    # Minimize the frontier width; H*W <= 200 implies min(H,W) <= 14.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Fixed equal neighbors cannot be repaired by filling unknown cells.
    # In particular, ['1?322'] has zero completions, despite frozen test_05
    # expecting one.
    for r in range(H):
        for c in range(W):
            value = grid[r][c]
            if value != '?':
                if r and grid[r - 1][c] == value:
                    return 0
                if c and grid[r][c - 1] == value:
                    return 0

    mod = 998244353
    mask = (1 << (2 * W)) - 1
    upper_shift = 2 * (W - 1)
    choices = {
        (up, left, fixed): tuple(
            color for color in (1, 2, 3)
            if color != up and color != left and (not fixed or color == fixed)
        )
        for up in range(4)
        for left in range(4)
        for fixed in range(4)
    }
    # The frontier stores the most recent W cells, oldest in the high bits.
    # Zero stands for a missing neighbor before the first row is filled.
    dp = {0: 1}
    for row in grid:
        for c, value in enumerate(row):
            fixed = 0 if value == '?' else int(value)
            next_dp = {}
            for frontier, count in dp.items():
                up = frontier >> upper_shift
                left = frontier & 3 if c else 0
                shifted = (frontier << 2) & mask
                for color in choices[up, left, fixed]:
                    state = shifted | color
                    next_dp[state] = (next_dp.get(state, 0) + count) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

